// AUTO-GENERATED BY silc — DO NOT EDIT
/** Async Silclm strategic layer — never blocks the combat loop. */

import type { Possession } from "../framework/mode.ts";
import type { Resources } from "../kernel/resources.ts";
import type { GameSystem } from "../kernel/systems.ts";
import type { EntityId, World } from "../kernel/world.ts";
import type { MindDirective } from "./ai.ts";
import type { CombatState } from "./weapons.ts";

type QueueItem = {
  entityId: EntityId;
  persona: string;
  cadence: number;
  lastAt: number;
  inflight: boolean;
};

export function createCognitionSystem(
  world: World,
  resources: Resources,
  possession: Possession,
  combat: CombatState,
): GameSystem {
  const minds = new Map<EntityId, QueueItem>();
  let clock = 0;
  return {
    name: "cognition",
    order: 28,
    init() {
      for (const [id] of world.query("mind")) {
        const mind = world.getComponent<{ ref?: string | null; cadenceS?: number }>("mind", id);
        const data = mind?.ref ? resources.data[mind.ref] ?? {} : {};
        minds.set(id, {
          entityId: id,
          persona: String(data.persona ?? "Hostile megastructure operative."),
          cadence: Number(mind?.cadenceS ?? data.cadence_s ?? 4),
          lastAt: -999,
          inflight: false,
        });
      }
    },
    update(ctx) {
      clock += ctx.dt;
      const playerId = possession.pawnId;
      if (playerId == null) return;
      const playerPos = world.worldPosition(playerId);

      for (const [id, slot] of minds) {
        if (world.getComponent("dead", id)) continue;
        const npcPos = world.worldPosition(id);
        const dist = Math.hypot(playerPos.x - npcPos.x, playerPos.z - npcPos.z);
        const attrs =
          world.getComponent<{ name: string; value: number }[]>("attributes", id) ?? [];
        const hp = attrs.find((a) => a.name === "health")?.value ?? 100;
        const shouldThink =
          !slot.inflight &&
          clock - slot.lastAt >= slot.cadence &&
          (dist < 35 || hp < 50);

        if (!shouldThink) continue;
        slot.inflight = true;
        slot.lastAt = clock;
        const snapshot = {
          self: {
            name: world.nameOf(id),
            hp,
            pos: npcPos,
            archetype: world.getComponent<{ archetype?: string }>("npc", id)?.archetype,
          },
          player: { hp: combat.health, pos: playerPos, score: combat.score },
          alliesAlive: [...world.query("npc")].filter(([nid]) => !world.getComponent("dead", nid))
            .length,
        };
        void requestDirective(slot.persona, snapshot)
          .then((directive) => {
            if (!directive) return;
            world.addComponent("directive", id, directive);
            void resources.telemetry.event("cognition", {
              entity: world.nameOf(id),
              tactic: directive.preferred_tactic,
            });
          })
          .finally(() => {
            slot.inflight = false;
          });
      }
    },
  };
}

async function requestDirective(
  persona: string,
  snapshot: unknown,
): Promise<MindDirective | null> {
  try {
    const res = await fetch("/api/cognition", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ persona, context: snapshot }),
    });
    if (!res.ok) return fallbackDirective(snapshot);
    const body = (await res.json()) as { ok?: boolean; directive?: MindDirective };
    if (!body.ok || !body.directive) return fallbackDirective(snapshot);
    return normalize(body.directive);
  } catch {
    return fallbackDirective(snapshot);
  }
}

function fallbackDirective(snapshot: unknown): MindDirective {
  const hp = Number((snapshot as { self?: { hp?: number } })?.self?.hp ?? 100);
  return {
    aggression: hp < 40 ? 0.35 : 0.75,
    preferred_tactic: hp < 40 ? "retreat" : Math.random() < 0.4 ? "flank_left" : "suppress",
    bark: hp < 40 ? "Falling back!" : "Contact!",
    ttl_s: 4,
    revision: Date.now(),
  };
}

function normalize(d: MindDirective): MindDirective {
  const allowed = new Set([
    "suppress",
    "flank_left",
    "flank_right",
    "push",
    "retreat",
    "hold",
  ]);
  const tactic = allowed.has(d.preferred_tactic) ? d.preferred_tactic : "suppress";
  return {
    aggression: Math.max(0, Math.min(1, Number(d.aggression ?? 0.6))),
    preferred_tactic: tactic,
    bark: typeof d.bark === "string" ? d.bark.slice(0, 80) : undefined,
    ttl_s: Math.max(1, Math.min(12, Number(d.ttl_s ?? 4))),
    revision: Number(d.revision ?? Date.now()),
  };
}
